    requestProps: LoadMoreFuncProps<T>;
    /**LoadMore组件参数 */
    tipProps?: Pick<LoadMoreProps, 'style' | 'endTip' | 'loadingTip'>;
    loadRef?: React.MutableRefObject<LoadMoreLayoutParams | null>;
}

