        </div>
    );
}

export default function PaymentPopup({
    className,
    prefixClass = 'my-payment-popup',
    productData,
    productKey,
    sceneKey,
    visible,
    title = '订单确认',
    intervalTime = 2000,
    intervalCount = VERIFY_COUNT,
    event = 'dy_dxgmjh_ddzftc', // 订阅_单项购买计划_订单支付弹窗
    autoReportBi = true,
    onVisibleChange,
    onCancel,
    onPaymentChange,
    buttonProps = {},
    onButtonClick,
    onPaySuccess,
    onPayFail,
    drawerProps,
